const principal='12345678-1234-1234-1234-123456789abc',key='22345678-1234-1234-1234-123456789abc',batch='32345678-1234-1234-1234-123456789abc',release='42345678-1234-1234-1234-123456789abc',snapshot='52345678-1234-1234-1234-123456789abc',event='62345678-1234-1234-1234-123456789abc';
const target=()=>({deployment_no:'DEP-1',batch_no:'BATCH-1'});
const context=()=>({...target(),batch_id:batch,release_id:release,snapshot_id:snapshot,history_state:'IMPORTED',expected_revision:0,predecessor_id:null,started_at:'2026-01-01T00:00:00.000000Z',ended_at:'2026-01-02T00:00:00.000000Z',changeover_id:null,note:'original note'});
const command=()=>({operation:'batch-correction',target:target(),context:context(),body:{request_id:key,expected_revision:0,predecessor_id:null,started_at:null,ended_at:null,changeover_id:null,note:null,correction_reason:'Correct mistaken note'}});
const eventNo=c=>'EVT-BC-'+c.body.request_id.replaceAll('-','');
const receipt=c=>({operation:c.operation,target:c.target,request_id:c.body.request_id,audit_event_no:eventNo(c),result:{batch_id:c.context.batch_id,batch_no:c.target.batch_no,release_id:c.context.release_id,snapshot_id:c.context.snapshot_id,started_at:c.body.started_at??c.context.started_at,ended_at:c.body.ended_at??c.context.ended_at,changeover_id:c.body.changeover_id,note:c.body.note,correction_reason:c.body.correction_reason,revision:c.body.expected_revision+1,predecessor_id:c.body.predecessor_id}});
